// What the Naming cops share: Ruby 3.3's `[[:upper:]]`, `[[:lower:]]` and
// `[[:digit:]]` past ASCII (tables generated from Ruby 3.3.6, each range
// twelve hex digits: first and last code point), ConfigurableNaming's
// snake_case format with ConfigurableFormatting#class_emitter_method?, and the
// UncommunicativeName mixin.
//
// Ported from RuboCop 1.92.2 (MIT License, Copyright (c) 2012-24 Bozhidar
// Batsov).

import { NT_CLASS, NT_DEFS, NT_KWRESTARG, NT_MLHS, NT_RESTARG, rbTypeName, V_NIL, vTag, VT_SYM } from "../ast";
import { RbCop } from "../cop";
import { RbSource } from "../source";

/** `[[:upper:]]` past ASCII. */
const NMH_UPPER: string =
  "";

/** `[[:lower:]]` past ASCII. */
const NMH_LOWER: string =
  "";

/** `[[:digit:]]` past ASCII. */
const NMH_DIGIT: string =
  "";

/** Six hex digits of `t` at `i`. */
const nmhHex6 = (t: string, i: i32): i32 => {
  let v = 0;
  for (let j = 0; j < 6; j++) {
    const d = t.charCodeAt(i + j);
    v = v * 16 + (d <= 57 ? d - 48 : d - 87);
  }
  return v;
};

/** Whether code point `c` is in a range table. */
const nmhInTable = (t: string, c: i32): boolean => {
  let lo = 0;
  let hi = toI32(t.length) / 12 - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const s = nmhHex6(t, mid * 12);
    const e = nmhHex6(t, mid * 12 + 6);
    if (c < s) {
      hi = mid - 1;
    } else if (c > e) {
      lo = mid + 1;
    } else {
      return true;
    }
  }
  return false;
};

/** `[[:upper:]]` on a code point. */
export const nmhUpper = (c: i32): boolean => (c < 128 ? c >= 65 && c <= 90 : nmhInTable(NMH_UPPER, c));

/** `[[:lower:]]` on a code point. */
export const nmhLower = (c: i32): boolean => (c < 128 ? c >= 97 && c <= 122 : nmhInTable(NMH_LOWER, c));

/** `[[:digit:]]` on a code point (`\d` is ASCII only). */
export const nmhDigit = (c: i32): boolean => (c < 128 ? c >= 48 && c <= 57 : nmhInTable(NMH_DIGIT, c));

/** `\d`. */
export const nmhAsciiDigit = (c: i32): boolean => c >= 48 && c <= 57;

/** The code points of a UTF-8 string. */
export const nmhCps = (s: string): i32[] => {
  const out: i32[] = [];
  const n = toI32(s.length);
  let i = 0;
  while (i < n) {
    const b = s.charCodeAt(i);
    if (b < 0x80) {
      out.push(b);
      i++;
    } else if (b < 0xe0 && i + 1 < n) {
      out.push(((b & 0x1f) << 6) | (s.charCodeAt(i + 1) & 0x3f));
      i += 2;
    } else if (b < 0xf0 && i + 2 < n) {
      out.push(((b & 0x0f) << 12) | ((s.charCodeAt(i + 1) & 0x3f) << 6) | (s.charCodeAt(i + 2) & 0x3f));
      i += 3;
    } else if (i + 3 < n) {
      out.push(((b & 0x07) << 18) | ((s.charCodeAt(i + 1) & 0x3f) << 12) | ((s.charCodeAt(i + 2) & 0x3f) << 6) | (s.charCodeAt(i + 3) & 0x3f));
      i += 4;
    } else {
      out.push(b);
      i++;
    }
  }
  return out;
};

/** Whether any code point of `s` is `[[:upper:]]`. */
export const nmhHasUpper = (s: string): boolean => {
  for (const c of nmhCps(s)) {
    if (nmhUpper(c)) {
      return true;
    }
  }
  return false;
};

/**
 * ConfigurableNaming's snake_case: `/^@{0,2}[\d[[:lower:]]_]+[!?=]?$/` (on
 * any line of the name).
 */
export const nmhSnakeCase = (name: string): boolean => {
  const cs = nmhCps(name);
  let ls = 0;
  for (let i = 0; i <= cs.length; i++) {
    if (i < cs.length && cs[i] !== 10) {
      continue;
    }
    // One line: [ls, i).
    let p = ls;
    let at = 0;
    while (p < i && at < 2 && cs[p] === 64) {
      p++;
      at++;
    }
    // `@{0,2}` backtracks: an `@` it takes is never in the class anyway.
    let q = p;
    while (q < i && (nmhAsciiDigit(cs[q]) || nmhLower(cs[q]) || cs[q] === 95)) {
      q++;
    }
    if (q > p && (q === i || (q + 1 === i && (cs[q] === 33 || cs[q] === 63 || cs[q] === 61)))) {
      return true;
    }
    ls = i + 1;
  }
  return false;
};

/** ConfigurableFormatting#class_emitter_method?: a `def self.Foo` beside `class Foo`. */
export const nmhClassEmitter = (src: RbSource, n0: i32, name: string): boolean => {
  const a = src.a;
  let n = n0;
  if (src.parent(n) === V_NIL || a.type(n) !== NT_DEFS) {
    return false;
  }
  while (src.parent(n) !== V_NIL && a.type(src.parent(n)) === NT_DEFS) {
    n = src.parent(n);
  }
  const p = src.parent(n);
  if (p === V_NIL) {
    return false;
  }
  for (let i = 0; i < a.nKid(p); i++) {
    const c = a.kid(p, i);
    if (a.isNode(c) && a.type(c) === NT_CLASS) {
      const id = a.kid(c, 0);
      if (src.src(a.exS(id), a.exE(id)) === name) {
        return true;
      }
    }
  }
  return false;
};

/** Node#to_s (to_sexp) of an argument-list node. */
export const nmhSexp = (src: RbSource, n: i32, indent: i32): string => {
  const a = src.a;
  const out: string[] = [];
  for (let i = 0; i < indent; i++) {
    out.push("  ");
  }
  out.push("(");
  const ty = rbTypeName(a.type(n));
  for (let i = 0; i < toI32(ty.length); i++) {
    const c = ty.charCodeAt(i);
    out.push(c === 95 ? "-" : ty.substring(i, i + 1));
  }
  for (let i = 0; i < a.nKid(n); i++) {
    const k = a.kid(n, i);
    if (a.isNode(k)) {
      out.push("\n");
      out.push(nmhSexp(src, k, indent + 1));
    } else {
      out.push(" ");
      out.push(a.inspect(k));
    }
  }
  out.push(")");
  return out.join("");
};

/** String#size (code points). */
export const nmhSize = (s: string): i32 => nmhCps(s).length;

/**
 * UncommunicativeName#check on an args node: an offense at each argument
 * whose name (leading underscores dropped) has a capital letter or is
 * shorter than minLen (AllowNamesEndingInNumbers: true, ForbiddenNames: []).
 * `allowed` is the AllowedNames list as " a b ".
 */
export const nmhUncommunicative = (c: RbCop, src: RbSource, args: i32, minLen: i32, allowed: string): void => {
  const a = src.a;
  for (let i = 0; i < a.nKid(args); i++) {
    const arg = a.kid(args, i);
    if (!a.isNode(arg) || a.nKid(arg) === 0) {
      continue;
    }
    const nc = a.kid(arg, 0);
    if (nc === V_NIL) {
      continue;
    }
    // name_child.to_s: a symbol's name, or a node's s-expression (mlhs).
    const full = a.isNode(nc) ? nmhSexp(src, nc, 0) : vTag(nc) === VT_SYM ? a.text(nc) : a.inspect(nc);
    if (full === "_") {
      continue;
    }
    let k = 0;
    while (k < toI32(full.length) && full.charCodeAt(k) === 95) {
      k++;
    }
    const name = full.substring(k, toI32(full.length));
    if (allowed.indexOf(` ${name} `) >= 0) {
      continue;
    }
    let len = nmhSize(full);
    if (a.type(arg) === NT_RESTARG) {
      len += 1;
    }
    if (a.type(arg) === NT_KWRESTARG) {
      len += 2;
    }
    const s = a.exS(arg);
    if (nmhHasUpper(name)) {
      c.offense(s, s + len);
    }
    if (nmhSize(name) < minLen) {
      c.offense(s, s + len);
    }
  }
};

/** Whether n is an mlhs (its first child is a node). */
export const nmhIsMlhs = (src: RbSource, n: i32): boolean => src.a.isNode(n) && src.a.type(n) === NT_MLHS;
